  async initUtxoStore(addr) {
    try {
      this.utxoStore = [];
      const utxos = await this.ar.getUtxos(addr);
      if (utxos.status > 399) {
        throw new Error(utxos.message);
      }
      this.utxoStore = utxos;
      return this.utxoStore;
    } catch (err) {
      console.error("Error in utxos.js/initUtxoStore()");
      throw err;
    }
  }
